#include "../Source/ProjectIO.h"
#include <iostream>
#include <stdexcept>
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
int main(){try{
    auto p=fga::newProject(6);p.name="Garage – progetto";p.tracks[0].clips[0].notes.push_back({.125,1.375,65,117,2});p.tracks[0].clips[0].notes.push_back({.000012345678901234567,1./960.,110,87,0});p.tracks[2].locked=true;p.tracks[1].instrument="plugin";p.tracks[1].instrumentPath="/not/installed/Test.vst3";p.tracks[1].instrumentState="0123-state";p.tracks[5].gain=.317;p.tracks[5].pan=-.23;p.loop=true;p.loopStart=32;p.loopEnd=96;p.settings.guitarLead=true;p.settings.songMinutes=6.5;p.tracks[3].engine.laneShift[5]=23;p.tracks[3].engine.laneVolume[5]=.37;p.tracks[3].engine.laneOctave[1]=-1;p.tracks[3].engine.laneMute[8]=true;p.tracks[0].engine.pattern=12;p.tracks[0].engine.gate=.78;p.tracks[0].engine.reverb=.37;p.settings.chordSteps=8;p.tracks[0].engine.inversions[2]=-2;p.tracks[0].engine.userRight[3]='X';p.tracks[0].engine.userVelRight[3]=89;p.tracks[0].engine.velocityOrder={3,2,1,0};p.tracks[0].engine.segmentLocked[1]=true;p.tracks[0].engine.riffSeed=987;p.tracks[0].engine.humanizeSeed=456;p.tracks[0].engine.pumpRate=2;p.tracks[0].engine.pedalCC=true;p.normalise();
    p.tracks[4].volume.enabled=true;p.tracks[4].volume.points={{0,1,.5},{17.25,.3,-.8},{p.length(),0,0}};
    auto text=juce::JSON::toString(fga::projectJson(p),false,17);auto json=juce::JSON::parse(text);fga::Project restored;auto r=fga::projectFromJson(json,restored);check(r.wasOk(),"JSON parse");auto round=juce::JSON::toString(fga::projectJson(restored),false,17);if(round!=text){int diff=0;while(diff<std::min(round.length(),text.length())&&round[diff]==text[diff])++diff;std::cerr<<"round-trip difference at "<<diff<<"\noriginal: "<<text.substring(std::max(0,diff-70),diff+160)<<"\nrestored: "<<round.substring(std::max(0,diff-70),diff+160)<<"\n";}check(round==text,"stable project round trip");for(size_t ti=0;ti<p.tracks.size();++ti)for(size_t si=0;si<p.sections.size();++si){const auto& original=p.tracks[ti].clips[si].notes;const auto& loaded=restored.tracks[ti].clips[si].notes;check(original.size()==loaded.size(),"note count preserved");for(size_t ni=0;ni<original.size();++ni)check(std::abs(original[ni].start-loaded[ni].start)<1e-12&&std::abs(original[ni].length-loaded[ni].length)<1e-12,"sub-tick timing preserved");}
    auto tmp=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("arranger-io-tests","",false);tmp.createDirectory();auto file=tmp.getChildFile("song.fga");check(fga::saveProject(p,file).wasOk(),"atomic save");check(fga::loadProject(file,restored).wasOk(),"load");
    auto bytes=fga::midiFile(p,0);auto midi=tmp.getChildFile("piano.mid");midi.replaceWithData(bytes.data(),bytes.size());fga::Clip imported;check(fga::importMidi(midi,imported,p.length()).wasOk(),"MIDI import");size_t expected=0;for(const auto& c:p.tracks[0].clips)expected+=c.notes.size();check(imported.notes.size()>expected*.95,"MIDI matched note pairs");
    check(fga::projectFromJson(juce::var(),restored).failed(),"invalid format rejected");json.getDynamicObject()->setProperty("version",999);check(fga::projectFromJson(json,restored).failed(),"future schema rejected");json=juce::JSON::parse(text);json.getDynamicObject()->setProperty("tracks",juce::Array<juce::var>());check(fga::projectFromJson(json,restored).failed(),"missing tracks rejected");
    auto legacy=fga::projectJson(p);for(auto& track:*legacy["tracks"].getArray())track.getDynamicObject()->removeProperty("volumeAutomation");check(fga::projectFromJson(legacy,restored).wasOk()&&!restored.tracks[4].volume.enabled&&restored.tracks[4].volume.points.empty(),"old projects load with bypassed empty automation");
    tmp.deleteRecursively();std::cout<<"Project persistence, schema validation and MIDI import passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
